(175, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Shares relevant up-to-date ideas during faculty meetings', 'likert', NULL, 1, 1, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(176, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Shares ideas with other members of the unit on how to teach a subject.', 'likert', NULL, 1, 2, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(177, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Volunteers to participate in committee work.', 'likert', NULL, 1, 3, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(178, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Accepts responsibilities willingly.', 'likert', NULL, 1, 4, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(179, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Attends faculty meetings and other school activities regularly and promptly.', 'likert', NULL, 1, 5, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(180, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Accomplishes assigned reports and other tasks accurately and promptly as member of a committee.', 'likert', NULL, 1, 6, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(181, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Possesses pleasant disposition and helps maintain esprit de corps by relating harmoniously with colleagues, administrative staff, and students.', 'likert', NULL, 1, 7, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(182, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Communicates ideas clearly and accurately.', 'likert', NULL, 1, 8, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(183, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Shows open-mindedness by respecting the ideas of others.', 'likert', NULL, 1, 9, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(184, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Shows intellectual honesty by giving due recognition to the works of others.', 'likert', NULL, 1, 10, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(185, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Shows concern and sincerity in dealing with others.', 'likert', NULL, 1, 11, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(186, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Respects dignity of others by not speaking ill of them.', 'likert', NULL, 1, 12, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(187, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Helps maintain an academic atmosphere in the unit and school as a whole.', 'likert', NULL, 1, 13, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(188, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'Shows evidence of commitment to the mission of the school.', 'likert', NULL, 1, 14, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(189, 6, 33, NULL, 'peer', 'Faculty Peer Collaboration & Professionalism', 'In sum, tries to exhibit exemplary behavior of a true professional.', 'likert', NULL, 1, 15, 1, '2026-09-28 15:44:49', '2026-09-28 15:44:49'),
(190, 7, 34, NULL, 'student', 'A. MASTERY OF SUBJECT MATTER (KAHUSAYAN SA PAKSANG ARALIN)', 'Discusses/Elaborates/Explains the lesson thoroughly without directly reading from books.', 'likert', NULL, 1, 1, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(191, 7, 34, NULL, 'student', 'A. MASTERY OF SUBJECT MATTER (KAHUSAYAN SA PAKSANG ARALIN)', 'Provides adequate and relevant examples and demonstrations to illustrate concepts and skills in the subject matter.', 'likert', NULL, 1, 2, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(192, 7, 34, NULL, 'student', 'A. MASTERY OF SUBJECT MATTER (KAHUSAYAN SA PAKSANG ARALIN)', 'Cites, relates, ties up lessons with other disciplines/subjects, when applicable.', 'likert', NULL, 1, 3, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(193, 7, 34, NULL, 'student', 'A. MASTERY OF SUBJECT MATTER (KAHUSAYAN SA PAKSANG ARALIN)', 'Answers students’ questions/clarifications clearly.', 'likert', NULL, 1, 4, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(194, 7, 34, NULL, 'student', 'A. MASTERY OF SUBJECT MATTER (KAHUSAYAN SA PAKSANG ARALIN)', 'Discusses considerable coverage of topics per session within the learning capabilities of students.', 'likert', NULL, 1, 5, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(195, 7, 35, NULL, 'student', 'B. COMMUNICATION SKILLS (KASANAYAN SA PAKIKIPAG-UGNAY)', 'Communicates in clear, correct and coherent language that is suited to the student’s level of understanding.', 'likert', NULL, 1, 6, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(196, 7, 35, NULL, 'student', 'B. COMMUNICATION SKILLS (KASANAYAN SA PAKIKIPAG-UGNAY)', 'Shifts to another language/the vernacular WHEN NECESSARY for clearer communication.', 'likert', NULL, 1, 7, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(197, 7, 35, NULL, 'student', 'B. COMMUNICATION SKILLS (KASANAYAN SA PAKIKIPAG-UGNAY)', 'Uses language that inspires students to listen.', 'likert', NULL, 1, 8, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(198, 7, 35, NULL, 'student', 'B. COMMUNICATION SKILLS (KASANAYAN SA PAKIKIPAG-UGNAY)', 'Speaks at appropriate speed and volume.', 'likert', NULL, 1, 9, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(199, 7, 35, NULL, 'student', 'B. COMMUNICATION SKILLS (KASANAYAN SA PAKIKIPAG-UGNAY)', 'Exhibits appropriate facial expressions and gestures and maintain eye contact with students when speaking.', 'likert', NULL, 1, 10, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(200, 7, 36, NULL, 'student', 'C. CLASSROOM MANAGEMENT (PAMAMAHALA SA SILID-ARALAN)', 'Capable of maintaining classroom discipline.', 'likert', NULL, 1, 11, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(201, 7, 36, NULL, 'student', 'C. CLASSROOM MANAGEMENT (PAMAMAHALA SA SILID-ARALAN)', 'Begins the class on time and does not dismiss before time.', 'likert', NULL, 1, 12, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(202, 7, 36, NULL, 'student', 'C. CLASSROOM MANAGEMENT (PAMAMAHALA SA SILID-ARALAN)', 'Provides an environment that is pleasant and conducive to learning.', 'likert', NULL, 1, 13, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
(203, 7, 36, NULL, 'student', 'C. CLASSROOM MANAGEMENT (PAMAMAHALA SA SILID-ARALAN)', 'Holds the attention/interest of students and is alert to respond to students’ reactions.', 'likert', NULL, 1, 14, 1, '2026-09-28 15:55:57', '2026-09-28 15:55:57'),
