(287, 8, 44, 26, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I make my time and talents available beyond the classroom helping students through extra academic assistance, coaching or managing of teams, clubs or other activities.', 'likert', NULL, 1, 73, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(288, 8, 44, 27, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I encourage the students to take action to improve the school environment, to respect the school property and that of others.', 'likert', NULL, 1, 74, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(289, 8, 44, 27, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'In all contacts with students in the halls, on the playing field or wherever, I encourage goodwill towards the school.', 'likert', NULL, 1, 75, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(290, 8, 44, 27, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I show concern for the total welfare of my students rather than achievement in a particular subject.', 'likert', NULL, 1, 76, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(291, 8, 44, 27, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I take corrective action outside of my classroom when necessary.', 'likert', NULL, 1, 77, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(292, 8, 44, 28, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I discourage harmful gossip and chronic complaining in the staff room.', 'likert', NULL, 1, 78, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(293, 8, 44, 28, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I support the policies of the school and ensure that my students understand and adhere to these policies.', 'likert', NULL, 1, 79, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(294, 8, 44, 28, 'self', 'AREA OF RESPONSIBILITY No. 6. - CONTRIBUTION TO THE TOTAL SCHOOL EFFORT', 'I bring student reaction to school policy to the attention of the administration, and suggest modification where applicable.', 'likert', NULL, 1, 80, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59');
