INSERT INTO `evaluation_subheadings` (`id`, `section_id`, `title`, `description`, `order_num`, `created_at`, `updated_at`) VALUES
(6, 39, 'I create and maintain an atmosphere for learning.', NULL, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(7, 39, 'I provide a motivational environment for my students.', NULL, 2, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(8, 39, 'I maintain a judicious balance between teacher-centered and student-centered activities.', NULL, 3, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(9, 39, 'I use effective questioning techniques.', NULL, 4, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(10, 39, 'I use techniques that make clear the purpose and content of each lesson.', NULL, 5, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(11, 40, 'I use varied and effective methods of presentation appropriate to the lesson content.', NULL, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(12, 40, 'I provide written and oral assignments requiring analytical and critical thinking.', NULL, 2, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(13, 40, 'I evaluate effectively, thereby improving both teaching and learning.', NULL, 3, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(14, 40, 'I utilize community resources to enrich the classroom program.', NULL, 4, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(15, 41, 'My classroom procedures are designed to develop a positive learning environment.', NULL, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(16, 41, 'I have an effective method for dealing with clerical matters.', NULL, 2, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(17, 42, 'I strive to upgrade my professional competence.', NULL, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(18, 42, 'I make use of available means of evaluation to improve my teaching.', NULL, 2, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(19, 42, 'I take an active part in continuing curriculum development.', NULL, 3, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(20, 42, 'I recognize the major objectives to be achieved in my subject area and work towards their attainment.', NULL, 4, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(21, 43, 'I am consistently fair and impartial with students.', NULL, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(22, 43, 'I recognize my responsibilities in helping students to mature socially and to achieve self-realization.', NULL, 2, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(23, 43, 'I recognize that my attitude and efficiency in my work has an effect on other staff members.', NULL, 3, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(24, 43, 'I try to promote a positive climate in the school.', NULL, 4, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(25, 43, 'I make use of my contacts with parents and other concerned adults to promote confidence and goodwill towards the school program and staff.', NULL, 5, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(26, 44, 'In addition to my regular duties as a classroom teacher, I accept willingly extra duties within the school.', NULL, 1, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(27, 44, 'My concern for my students extends beyond the teacher-student relationship.', NULL, 2, '2026-09-28 15:55:59', '2026-09-28 15:55:59'),
(28, 44, 'I accept administrative decisions in good faith and make use of the proper channels to suggest modifications to those decisions with which I disagree.', NULL, 3, '2026-09-28 15:55:59', '2026-09-28 15:55:59');
